const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'⌂',projects:'▦',agents:'✧',github:'⑂',deploy:'↗',settings:'⚙',docs:'≡'};
const samples=[{name:'Customer support copilot',type:'Agentic app',framework:'LangGraph',desc:'Answer customer questions using your knowledge base and route complex cases.'},{name:'Research analyst',type:'Multi-agent workflow',framework:'CrewAI',desc:'Research a topic, validate sources, and produce a cited report.'},{name:'Sales briefing agent',type:'Agentic app',framework:'AutoGen',desc:'Prepare account briefings from company information and CRM context.'}];
const seed={user:null,projects:[],active:null,view:'home',panel:'chat',canvas:'preview',model:'Auto · best fit',mode:'builder',modal:null,mobile:false,selectedFile:'src/App.tsx',toast:null};
let state={...seed,...JSON.parse(localStorage.getItem('architect2-demo')||'{}'),modal:null,toast:null};
state.projects=(state.projects||[]).map(p=>({...p,messages:p.messages||[],events:p.events||[],queue:(p.queue||[]).map(task=>task.status==='running'?{...task,status:'queued'}:task),queuePaused:!!p.queuePaused}));
let queueTimer=null;
function save(){let {modal,toast,...persist}=state;localStorage.setItem('architect2-demo',JSON.stringify(persist))}
function set(o){Object.assign(state,o);save();render()}
function project(){return state.projects.find(x=>x.id===state.active)}
function updateProject(o){let p=project();if(!p)return;Object.assign(p,o);save();render()}
function notice(s){state.toast=s;render();setTimeout(()=>{state.toast=null;render()},3000)}
function nav(v){set({view:v,modal:null})}
function auth(){return `<div class="auth"><div class="auth-art"><div class="mark"><span class="brand">A²</span> ARCHITECT</div><div><span class="eyebrow">Architect 2.0</span><h1>Start with an idea.<br>Take it all the way.</h1><p class="muted">A single workspace to build, inspect, connect and deploy intelligent applications.</p></div><span class="hint">An interactive product prototype · Sign-in is stored on this device</span></div><div class="auth-form"><div class="inner"><span class="eyebrow">Welcome</span><h2>Create your workspace</h2><p class="muted">Explore the full building flow. No account or payment required.</p><label class="field"><span>Your name</span><input id="auth-name" placeholder="Shreyash" autocomplete="name" value="${esc(state.pendingName||'')}"></label><label class="field"><span>Email</span><input id="auth-email" type="email" placeholder="you@example.com" autocomplete="email"></label><button class="btn primary" data-action="signin">Continue to Architect →</button><p class="fine">This demo uses local browser storage. Google and GitHub OAuth are represented as prototype flows.</p></div></div></div>`}
function sidebar(){return `<aside class="rail"><div class="brand" title="Architect 2.0">A²</div>${['home','projects','agents','github','deploy'].map(v=>`<button title="${v}" aria-label="${v}" class="${state.view===v?'active':''}" data-nav="${v}">${icons[v]}</button>`).join('')}<button class="bottom ${state.view==='settings'?'active':''}" title="Settings" aria-label="Settings" data-nav="settings">⚙</button></aside>`}
function modeSwitch(){return `<div class="mode-switch" role="group" aria-label="Workspace mode"><button class="${state.mode==='builder'?'selected':''}" data-mode-select="builder">◈ Builder</button><button class="${state.mode==='developer'?'selected':''}" data-mode-select="developer">⌘ Developer</button></div>`}
function header(){let p=project();return `<header class="top"><div class="crumb"><span>Workspace</span><span>/</span><strong>${state.view==='workspace'?esc(p?.name||'New project'):state.view[0].toUpperCase()+state.view.slice(1)}</strong>${state.view==='workspace'?'<span class="badge">● Preview ready</span>':''}</div><div class="top-actions">${state.view==='workspace'?`${modeSwitch()}<button class="btn ghost hide-mobile" data-action="share">Share</button><button class="btn primary" data-action="deploy-modal">Deploy ↗</button>`:'<button class="btn ghost hide-mobile" data-action="import">Import project</button><button class="btn primary" data-nav="home">+ New project</button>'}<button class="avatar" title="Account" data-nav="settings">${esc((state.user||'U').slice(0,1).toUpperCase())}</button></div></header>`}
function home(){return `<main class="page"><span class="eyebrow">YOUR WORKSPACE</span><h1>What will you build?</h1><p class="muted">Describe the app and agents you need. You can refine every detail in the workspace.</p><div class="home-grid"><div class="panel compose"><textarea id="home-prompt" placeholder="Build a customer support agent that answers from my knowledge base, escalates sensitive requests, and shows its reasoning to my team..."></textarea><div class="compose-footer"><div class="row"><button class="chip" data-action="import">⑂ Import repository</button><button class="chip" data-action="framework">✧ Framework: any</button></div><button class="btn primary" data-action="create">Build app →</button></div></div><div class="panel suggestions"><h3>Start with a direction</h3>${samples.map((x,i)=>`<button class="suggestion" data-action="sample" data-index="${i}">${esc(x.name)}<span>${esc(x.type)} · ${esc(x.framework)}</span></button>`).join('')}</div></div><div class="section-head"><h2>Recent projects</h2><button class="btn small ghost" data-nav="projects">View all →</button></div>${projectCards()}</main>`}
function projectCards(){return state.projects.length?`<div class="projects">${state.projects.slice().reverse().map(p=>`<button class="project" data-open="${p.id}"><span class="project-icon">✧</span><strong>${esc(p.name)}</strong><small>${esc(p.framework)} · ${esc(p.status||'In progress')}</small><div class="meta">Open workspace ↗</div></button>`).join('')}</div>`:`<div class="empty">No projects yet. Describe an app above or import a repository to begin.</div>`}
function projectsPage(){return `<main class="page"><span class="eyebrow">ALL PROJECTS</span><h1>Projects</h1><p class="muted">Resume a build or start from an existing codebase.</p><div class="row"><button class="btn primary" data-nav="home">+ Create project</button><button class="btn" data-action="import">Import repository</button></div><div class="section-head"><h2>Your work</h2><span class="hint">${state.projects.length} project${state.projects.length===1?'':'s'}</span></div>${projectCards()}</main>`}
function workspace(){let p=project();if(!p)return home();let tabs=state.mode==='builder'?['preview','agents','data','github','deploy']:['preview','code','agents','data','github','deploy','logs'];return `<div class="work"><section class="left-pane"><div class="pane-title"><strong>✧ Architect agent</strong><span class="badge">${esc(state.model)}</span></div><div class="tabs"><button data-panel="chat" class="${state.panel==='chat'?'selected':''}">Chat</button><button data-panel="activity" class="${state.panel==='activity'?'selected':''}">Activity</button><button data-panel="plan" class="${state.panel==='plan'?'selected':''}">Plan</button></div><div class="stream">${leftContent(p)}</div><div class="chat-compose"><div class="box"><textarea id="chat-input" placeholder="Describe the next change to queue…"></textarea><footer><button class="chip" data-action="model">${esc(state.model)} ⌄</button><div class="composer-actions"><span class="hint">⌘↵ adds to queue</span><button class="btn primary small" data-action="send">+ Add to queue</button></div></footer></div></div></section><section class="canvas"><div class="canvas-bar"><div class="view-tabs">${tabs.map(v=>`<button class="${state.canvas===v?'selected':''}" data-canvas="${v}">${v==='github'?'Git':v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><span class="mode-caption">${state.mode==='builder'?'Prompt & visual tools':'Code, runtime & precision tools'}</span></div><div class="canvas-body">${canvasContent(p)}</div></section></div>`}
function queuePanel(p){let queue=p.queue||[],active=queue.find(x=>x.status==='running'),pending=queue.filter(x=>x.status==='queued'),complete=queue.filter(x=>x.status==='done').slice(-1);if(!queue.length)return `<div class="queue-empty"><strong>Prompt queue</strong><span>Add several changes now. Architect will implement them one at a time.</span></div>`;let rows=[...(active?[active]:[]),...pending,...complete];return `<div class="prompt-queue"><div class="queue-head"><div><strong>Prompt queue</strong><span>${active?'1 running · ':''}${pending.length} waiting · sequential execution</span></div><div class="row">${(active||pending.length)?`<button class="queue-control" data-action="queue-pause">${p.queuePaused?'Resume':'Pause'}</button>`:''}${complete.length?'<button class="queue-control" data-action="queue-clear">Clear done</button>':''}</div></div>${rows.map((task,i)=>`<div class="queue-task ${task.status}"><span class="queue-status">${task.status==='running'?'●':task.status==='done'?'✓':pending.indexOf(task)+1}</span><div><strong>${esc(task.text)}</strong><small>${task.status==='running'?'Implementing focused change…':task.status==='done'?'Completed and verified':'Waiting for earlier prompts'}</small></div>${task.status==='queued'?`<button class="queue-remove" data-action="queue-remove" data-task="${task.id}" title="Remove queued prompt">×</button>`:''}</div>`).join('')}</div>`}
function leftContent(p){if(state.panel==='activity')return `<h3 class="subhead">Build activity</h3><p class="muted">Every action has a visible result and a recovery point.</p>${(p.events||[]).slice().reverse().map(e=>`<div class="step"><strong>${esc(e.title)}</strong>${esc(e.detail)}<div class="hint">${esc(e.time)}</div></div>`).join('')}`;if(state.panel==='plan')return `<h3 class="subhead">Build plan</h3><p class="muted">Each prompt follows a short plan: inspect the affected surface, make the smallest safe change, then run targeted checks.</p>${['Understand the requested outcome','Inspect only relevant files and symbols','Apply a focused implementation','Run targeted checks and review the diff','Connect GitHub','Deploy an immutable version'].map((x,i)=>`<div class="step"><strong>${i<4?'✓':'○'} ${x}</strong><span class="hint">${i<4?'Used for every queued prompt':'Available from the workspace'}</span></div>`).join('')}`;return `${queuePanel(p)}<div class="message assistant"><span class="label">Architect</span>I’ve prepared ${esc(p.name)} as an editable prototype. Queue multiple changes, inspect the suggested code, or configure agents before deploying.</div>${p.messages.map(m=>`<div class="message ${m.role}"><span class="label">${m.role==='user'?'You':'Architect'}</span>${esc(m.text)}</div>`).join('')}<div class="card"><h3>What to do next</h3><p>Review the preview and agent setup. Switch modes at the top at any time—the active project and queued work stay in place.</p><div class="row"><button class="btn small" data-canvas="agents">Inspect agents</button><button class="btn small" data-action="open-code">See code</button></div></div>`}
function preview(p){return `<div class="preview-tools"><div class="url-pill">🔒 ${esc(p.slug)}.preview.architect.local</div><div class="row"><button class="icon-btn" title="Desktop preview" data-action="desktop">▣</button><button class="icon-btn" title="Mobile preview" data-action="mobile">▯</button><button class="icon-btn" title="Refresh preview" data-action="refresh">↻</button></div></div><div class="preview ${state.mobile?'mobile':''}"><div class="preview-head"><span>✧ ${esc(p.name)}</span><button data-action="preview-interact">Try agent →</button></div><div class="preview-main"><span class="pill">BUILT WITH ARCHITECT</span><h1>${esc(p.name)} makes complex work feel simple.</h1><p>${esc(p.prompt)}</p><div class="cards"><div>✧<strong>Intelligent agent</strong>Configure the model, instructions and tools.</div><div>▤<strong>Clear workspace</strong>See outputs, history and human review.</div><div>↗<strong>Ready to ship</strong>Connect your repository and deploy.</div></div></div></div>`}
const codeFiles={'src/App.tsx':`import { AgentWorkspace } from './components/AgentWorkspace';\n\nexport default function App() {\n  return <AgentWorkspace />;\n}`, 'src/agents/main.ts':`import { createAgent } from '@architect/runtime';\n\nexport const agent = createAgent({\n  name: 'Main agent',\n  model: 'auto',\n  tools: ['knowledge_search'],\n  instructions: 'Help users with clear, verified answers.'\n});`, 'src/components/AgentWorkspace.tsx':`export function AgentWorkspace() {\n  return (\n    <main>\n      <h1>Welcome to your agentic app</h1>\n      <p>Connect a data source to begin.</p>\n    </main>\n  );\n}`, 'package.json':`{\n  "name": "architect-generated-app",\n  "scripts": { "dev": "vite", "build": "vite build" }\n}`};
function code(){return `<div class="code-wrap"><div class="files"><div class="hint">PROJECT FILES</div>${Object.keys(codeFiles).map(f=>`<button class="${state.selectedFile===f?'selected':''}" data-file="${f}">▤ ${f}</button>`).join('')}</div><div class="code-area"><div class="filename">${esc(state.selectedFile)} <span class="hint"> · illustrative scaffold</span></div><pre>${esc(codeFiles[state.selectedFile])}</pre><button class="btn small" data-action="copy-code">Copy file</button></div></div>`}
function logs(p){return `<div class="side-content"><span class="eyebrow">DEVELOPER CONTROLS</span><h2 class="subhead">Runs and recovery</h2><p class="muted">Inspect checks, command output and checkpoints before sending changes to Git.</p><div class="card"><h3>Latest run</h3><p>Project initialized · scaffold generated · preview prepared</p><pre style="white-space:pre-wrap;color:#b1c5d5;line-height:1.7;font-size:13px">$ install dependencies\n✓ sample scaffold ready\n$ build\n✓ preview ready\n\nDemo output: no command was executed in a sandbox.</pre></div><div class="card"><h3>Checkpoint 01 · Initial project</h3><p>Restore the initial prototype state if you want to explore a different direction.</p><button class="btn small" data-action="restore">Restore checkpoint</button></div></div>`}
function agents(p){return `<div class="side-content"><span class="eyebrow">AGENT STUDIO</span><h2 class="subhead">Design the intelligence</h2><p class="muted">Define roles, models and tools. Technical builders can take these decisions into their own framework.</p><div class="card"><span class="badge">● Configured</span><h3 style="margin-top:13px">Main agent</h3><p>${esc(p.agentGoal||'Handles the core user request, searches relevant context, and returns a helpful response.')}</p><div class="two"><label class="field"><span>Framework</span><select id="agent-framework"><option ${p.framework==='LangGraph'?'selected':''}>LangGraph</option><option ${p.framework==='CrewAI'?'selected':''}>CrewAI</option><option ${p.framework==='AutoGen'?'selected':''}>AutoGen</option><option ${p.framework==='OpenAI Agents SDK'?'selected':''}>OpenAI Agents SDK</option><option ${p.framework==='Custom'?'selected':''}>Custom</option></select></label><label class="field"><span>Model</span><select id="agent-model"><option>Auto · best fit</option><option>GPT family</option><option>Claude family</option><option>Gemini family</option><option>Open-source model</option></select></label></div><div class="row"><button class="btn small" data-action="save-agent">Save agent</button><button class="btn small" data-action="test-agent">Run test</button></div></div><div class="card"><h3>Tools and knowledge</h3><p>Add a knowledge source or a service that agents can call. Credentials will be requested when connected in a real deployment.</p><button class="btn small" data-action="tools">+ Add tool or knowledge</button></div><div class="card"><h3>Human review</h3><p>Pause before consequential actions and show the user exactly what the agent intends to do.</p><label><input type="checkbox" id="approval" ${p.approval?'checked':''}> Require approval before external actions</label></div></div>`}
function data(p){return `<div class="side-content"><span class="eyebrow">DATA & INTEGRATIONS</span><h2 class="subhead">Give your app context</h2><p class="muted">Connect data, add secrets and decide what each agent can access.</p><div class="two"><div class="card"><h3>Database</h3><p>Store users, conversations, tasks and application data.</p><button class="btn small" data-action="database">Set up database</button></div><div class="card"><h3>Knowledge base</h3><p>Bring files or a data source into the agent’s retrieval workflow.</p><button class="btn small" data-action="knowledge">Add source</button></div></div><div class="card"><h3>Environment variables</h3><p>Keep API keys and credentials outside source code. This prototype never asks you to enter real secrets.</p><button class="btn small" data-action="secrets">View secret flow</button></div></div>`}
function git(p){return `<div class="side-content"><span class="eyebrow">SOURCE CONTROL</span><h2 class="subhead">Keep your code yours</h2><p class="muted">Import, review changes and send work back to your repository.</p><div class="card"><h3>GitHub connection</h3><p>${p.github?`Connected to ${esc(p.repo||'your repository')}. This is a simulated connection for the prototype.`:'Install the Architect GitHub App on selected repositories, then choose a project and branch.'}</p><button class="btn" data-action="connect-github">${p.github?'Change repository':'Connect GitHub →'}</button></div><div class="card"><h3>Working branch</h3><p><code>architect/${esc(p.slug)}</code> · ${p.messages.length+3} suggested changes ready for review</p><div class="row"><button class="btn small" data-action="diff">View changes</button><button class="btn small" data-action="push">Push branch</button><button class="btn small" data-action="pr">Open pull request</button></div></div></div>`}
function deploy(p){return `<div class="side-content"><span class="eyebrow">DEPLOYMENTS</span><h2 class="subhead">Take it live</h2><p class="muted">Preview the release plan, verify environment requirements and publish an immutable version.</p><div class="card"><h3>Production release</h3><p>Source: current checkpoint · Target: managed cloud · Region: automatic</p><span class="badge ${p.status==='Published'?'':'warning'}">${p.status==='Published'?'● Live':'○ Not published'}</span>${p.status==='Published'?`<p style="margin-top:13px">Demo release URL: <code>https://${esc(p.slug)}.architect-demo.app</code></p>`:''}<div style="margin-top:16px"><button class="btn primary" data-action="deploy-modal">${p.status==='Published'?'Deploy update':'Configure deployment →'}</button></div></div><div class="card"><h3>Release checks</h3><ul class="timeline"><li>Source snapshot ready<small>Changes are captured before deployment.</small></li><li>Build and health check<small>Shown as a simulated verification in this prototype.</small></li><li>Secrets and domain<small>Configure separately from the interactive preview.</small></li></ul></div></div>`}
function canvasContent(p){return ({preview:()=>preview(p),code,agents:()=>agents(p),data:()=>data(p),github:()=>git(p),deploy:()=>deploy(p),logs:()=>logs(p)})[state.canvas]?.()||preview(p)}
function overview(section){let content={agents:['Agent library','Build across frameworks','Reusable agent roles, tool permissions, test runs and human approval.'],github:['GitHub','Bring your repository','Connect selected repositories, import a branch and inspect diffs before pushing.'],deploy:['Deployments','Ship with confidence','Review a checkpoint, release settings, build status and rollback path.'],settings:['Workspace settings','Make it yours','Manage your profile and choose how much detail Architect shows.']}[section];return `<main class="page"><span class="eyebrow">WORKSPACE</span><h1>${content[0]}</h1><p class="muted">${content[2]}</p><div class="card"><h3>${content[1]}</h3><p>${section==='settings'?'The prototype stores your workspace locally in this browser.':'Create or open a project to configure this feature in context.'}</p>${section==='settings'?`<div class="row"><button class="btn" data-action="mode">Mode: ${state.mode}</button><button class="btn danger" data-action="signout">Sign out</button></div>`:`<div class="row"><button class="btn primary" data-nav="home">Start a project</button>${state.projects.length?'<button class="btn" data-open="'+state.projects[0].id+'">Open recent project</button>':''}</div>`}</div></main>`}
function modal(){let p=project();switch(state.modal){case'import':return modalShell('Import a project','Continue building from an existing repository.',`<label class="field"><span>GitHub repository URL</span><input id="repo-url" placeholder="https://github.com/owner/repository"></label><label class="field"><span>Branch</span><input id="repo-branch" value="main"></label><p>In production, Architect installs a GitHub App on selected repositories, detects the runtime, restores secrets and boots an isolated sandbox. Here, import creates a local demo project.</p>`, 'Import project','import-confirm');case'github':return modalShell('Connect GitHub','Grant access to the repositories you choose.',`<label class="field"><span>Repository</span><input id="github-repo" placeholder="owner/repository"></label><p>This simulates GitHub App installation. No credentials or repository data are requested.</p>`,'Connect demo repository','github-confirm');case'deploy':return modalShell('Deploy app','Review the release before publishing.',`<div class="card"><h3>${esc(p?.name||'Project')}</h3><p>Source: saved project checkpoint<br>Target: managed cloud<br>Environment: production</p></div><label class="field"><span>App subdomain</span><input id="deploy-slug" value="${esc(p?.slug||'my-app')}"></label><p>Demo flow: the status and URL below are illustrative. This does not deploy the generated app.</p>`,'Simulate deployment','deploy-confirm');case'model':return modalShell('Choose a model','Switch models for future agent runs.',`<label class="field"><span>Model preference</span><select id="model-select">${['Auto · best fit','GPT family','Claude family','Gemini family','Open-source model'].map(x=>`<option ${state.model===x?'selected':''}>${x}</option>`).join('')}</select></label><p>Production routing would enforce tool compatibility, budgets, fallbacks and provider policies.</p>`,'Save preference','model-confirm');case'framework':return modalShell('Choose a framework','Architect can scaffold agent logic in the framework you prefer.',`<label class="field"><span>Agent framework</span><select id="framework-select">${['Auto-detect','LangGraph','CrewAI','AutoGen','OpenAI Agents SDK','Custom'].map(x=>`<option>${x}</option>`).join('')}</select></label>`,'Use framework','framework-confirm');case'tools':return modalShell('Add a tool','Choose what the agent needs to do.',`<div class="two"><div class="card"><h3>Knowledge search</h3><p>Retrieve context from your documents.</p></div><div class="card"><h3>External API</h3><p>Call a service with scoped credentials.</p></div></div><p>Tool permissions and credentials are reviewed before activation.</p>`,'Add demo tool','tools-confirm');case'share':return modalShell('Share workspace','Invite a collaborator with project-specific permissions.',`<label class="field"><span>Email address</span><input type="email" id="share-email" placeholder="teammate@example.com"></label><label class="field"><span>Role</span><select id="share-role"><option>Builder</option><option>Developer</option><option>Viewer</option></select></label><p>Invitations are illustrated here and are not sent.</p>`,'Preview invitation','share-confirm');default:return ''}}
function modalShell(title,sub,body,confirm,action){return `<div class="modal-bg" data-action="close-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2><p>${esc(sub)}</p>${body}<div class="modal-actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="${action}">${esc(confirm)}</button></div></div></div>`}
function render(){let content=state.user?`<div class="app mode-${state.mode}">${sidebar()}<div class="shell">${header()}${state.view==='home'?home():state.view==='workspace'?workspace():state.view==='projects'?projectsPage():overview(state.view)}</div></div>`:auth();$('#app').innerHTML=content+(state.modal?modal():'')+(state.toast?`<div class="toast" role="status">${esc(state.toast)}</div>`:'')}
function createFromPrompt(prompt,framework='Auto-detect',repo=''){const id=Date.now().toString(36);const name=repo?repo.split('/').filter(Boolean).pop().replace(/\.git$/,'').replace(/[-_]/g,' '):prompt.trim().replace(/[.!?].*$/,'').split(' ').slice(0,5).join(' ');let slug=(name||'new-app').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,35)||'new-app';let p={id,name:name||'New app',slug,prompt:prompt||`Imported from ${repo}`,framework:framework==='Auto-detect'?'LangGraph':framework,status:'In progress',github:!!repo,repo,messages:[],queue:[],queuePaused:false,events:[{title:'Preview prepared',detail:'Interactive product preview is ready.',time:'Just now'},{title:'Agent scaffold created',detail:'Suggested framework and agent roles.',time:'Just now'},{title:'Project created',detail:'Saved your starting request.',time:'Just now'}]};state.projects.push(p);set({active:id,view:'workspace',panel:'chat',canvas:'preview'});notice('Workspace ready · changes saved in this browser')}
function event(title,detail){let p=project();p.events.push({title,detail,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});save()}
function queuePrompt(text){let p=project(),task={id:Date.now().toString(36)+Math.random().toString(36).slice(2,5),text,status:'queued',createdAt:Date.now()};p.queue.push(task);p.events.push({title:'Prompt queued',detail:text,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});save();render();runNextPrompt(p.id);notice(p.queue.filter(x=>x.status==='queued').length>1?'Prompt added behind earlier work':'Prompt queued · execution starting')}
function runNextPrompt(projectId){let p=state.projects.find(x=>x.id===projectId);if(!p||p.queuePaused||p.queue.some(x=>x.status==='running'))return;let task=p.queue.find(x=>x.status==='queued');if(!task)return;task.status='running';task.startedAt=Date.now();p.messages.push({role:'user',text:task.text});p.events.push({title:'Prompt started',detail:'Inspecting the smallest relevant code surface.',time:'Now'});save();if(state.active===projectId)render();clearTimeout(queueTimer);queueTimer=setTimeout(()=>finishPrompt(projectId,task.id),1700)}
function finishPrompt(projectId,taskId){let p=state.projects.find(x=>x.id===projectId),task=p?.queue.find(x=>x.id===taskId);if(!p||!task)return;task.status='done';task.completedAt=Date.now();p.messages.push({role:'assistant',text:`Completed “${task.text}”. Short plan: inspect only affected files → apply a focused change → run targeted checks → review the diff. This prototype simulates execution; the production harness would stream real sandbox output and stop for a question only when ambiguity changes the implementation.`});p.events.push({title:'Queued prompt completed',detail:task.text,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});save();if(state.active===projectId)render();queueTimer=setTimeout(()=>runNextPrompt(projectId),450)}
document.addEventListener('click',e=>{let t=e.target.closest('[data-action],[data-nav],[data-open],[data-canvas],[data-panel],[data-file],[data-mode-select]');if(!t)return;if(t.dataset.nav){nav(t.dataset.nav);return}if(t.dataset.open){set({active:t.dataset.open,view:'workspace',canvas:'preview',panel:'chat'});runNextPrompt(t.dataset.open);return}if(t.dataset.modeSelect){let mode=t.dataset.modeSelect,canvas=state.canvas;if(mode==='builder'&&['code','logs'].includes(canvas))canvas='preview';set({mode,canvas});notice(`${mode==='builder'?'Builder':'Developer'} mode selected · work stays in progress`);return}if(t.dataset.canvas){set({canvas:t.dataset.canvas});return}if(t.dataset.panel){set({panel:t.dataset.panel});return}if(t.dataset.file){set({selectedFile:t.dataset.file});return}let a=t.dataset.action;if(a==='close-backdrop'&&e.target!==t)return;const v=id=>$(id)?.value?.trim()||'';switch(a){case'signin':{let name=v('#auth-name'),email=v('#auth-email');if(!name||!/^\S+@\S+\.\S+$/.test(email)){notice('Enter a name and valid email to continue');break}set({user:name,view:'home'});break}case'signout':set({user:null,view:'home'});break;case'create':{let prompt=v('#home-prompt');if(!prompt){notice('Describe what you want to build first');break}createFromPrompt(prompt,state.framework||'Auto-detect');break}case'sample':{let s=samples[Number(t.dataset.index)];createFromPrompt(s.desc,s.framework);break}case'import':case'framework':case'model':case'connect-github':case'deploy-modal':case'tools':case'share':set({modal:({'connect-github':'github','deploy-modal':'deploy'})[a]||a});break;case'close':case'close-backdrop':set({modal:null});break;case'import-confirm':{let repo=v('#repo-url');if(!/^https:\/\/github\.com\/[^/]+\/[^/]+/.test(repo)){notice('Enter a GitHub repository URL');break}createFromPrompt('', 'Auto-detect',repo);state.modal=null;render();break}case'github-confirm':{let repo=v('#github-repo');if(!/^[^/\s]+\/[^/\s]+$/.test(repo)){notice('Enter owner/repository');break}updateProject({github:true,repo});state.modal=null;event('GitHub connected','Prototype repository link configured.');notice('Demo repository connected');break}case'deploy-confirm':{let slug=v('#deploy-slug').toLowerCase().replace(/[^a-z0-9-]/g,'-');if(!slug){notice('Enter an app subdomain');break}updateProject({slug,status:'Published'});state.modal=null;state.canvas='deploy';event('Deployment simulated','Release checklist completed in demo mode.');notice('Demo release is ready · no production app was deployed');break}case'model-confirm':set({model:v('#model-select'),modal:null});notice('Model preference saved');break;case'framework-confirm':set({framework:v('#framework-select'),modal:null});notice('Framework preference saved');break;case'tools-confirm':state.modal=null;event('Tool added','Knowledge search was added to the agent plan.');notice('Demo tool added to plan');break;case'share-confirm':state.modal=null;notice('Invitation previewed · no email was sent');break;case'send':{let msg=v('#chat-input');if(!msg){notice('Write a request first');break}queuePrompt(msg);break}case'queue-pause':{let p=project();p.queuePaused=!p.queuePaused;save();render();if(!p.queuePaused)runNextPrompt(p.id);notice(p.queuePaused?'Prompt queue paused after the current task':'Prompt queue resumed');break}case'queue-remove':{let p=project();p.queue=p.queue.filter(x=>x.id!==t.dataset.task);save();render();notice('Queued prompt removed');break}case'queue-clear':{let p=project();p.queue=p.queue.filter(x=>x.status!=='done');save();render();break}case'open-code':set({mode:'developer',canvas:'code'});notice('Developer mode unlocked for precise code inspection');break;case'mode':{let mode=state.mode==='builder'?'developer':'builder',canvas=state.canvas;if(mode==='builder'&&['code','logs'].includes(canvas))canvas='preview';set({mode,canvas});notice(`${mode==='builder'?'Builder':'Developer'} mode selected`);break}case'mobile':set({mobile:true});break;case'desktop':set({mobile:false});break;case'refresh':notice('Preview refreshed');break;case'preview-interact':notice('Interactive agent testing is represented in the Agents tab');break;case'save-agent':updateProject({framework:v('#agent-framework'),approval:$('#approval')?.checked});event('Agent configuration saved','Framework and review preference updated.');notice('Agent configuration saved');break;case'test-agent':event('Agent test run','Simulated test completed. Connect a runtime for actual execution.');notice('Demo agent test completed');break;case'push':case'pr':notice(project()?.github?`Demo ${a==='push'?'push':'pull request'} flow shown · no GitHub write occurred`:'Connect a repository first');break;case'diff':set({canvas:'code',mode:'developer'});notice('Showing illustrative project files');break;case'restore':updateProject({messages:[],queue:[],queuePaused:false,status:'In progress'});event('Checkpoint restored','Returned to initial prototype state.');notice('Initial checkpoint restored');break;case'database':case'knowledge':case'secrets':notice('This integration is a guided prototype flow');break;case'copy-code':navigator.clipboard?.writeText(codeFiles[state.selectedFile]);notice('Illustrative code copied');break;default:break}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){if($('#chat-input')){e.preventDefault();$('[data-action="send"]')?.click()}else if($('#home-prompt')){e.preventDefault();$('[data-action="create"]')?.click()}}if(e.key==='Escape'&&state.modal)set({modal:null})});
render();
